      pt: ["3500 m: Altitude média do fundo do vale.", "100 km: Comprimento do Chadar Trek congelado.", "7135 m: Altitude do Nun Peak nas proximidades.", "10 meses: Duração do isolamento invernal.", "Século X: Fundação do mosteiro de Karsha.", "1980: Abertura de Ladakh ao turismo estrangeiro."],
